def _matvec(w, v, chunk=16384):
    """fp16 matrix x fp32 vector in chunks (keeps memory at a few hundred MB)."""
    import torch
    return torch.cat([w[i:i + chunk].float() @ v for i in range(0, w.shape[0], chunk)])


